import React, { useEffect, useMemo, useRef, useState } from "react";
import { Link, NavLink, Route, Routes, useNavigate, useParams } from "react-router-dom";
import { MapContainer, TileLayer, CircleMarker, Popup, useMap } from "react-leaflet";
import { Shield, Map, BarChart3, Building2, FileText, Siren, Menu, X, Search, ArrowRight, CheckCircle2, AlertTriangle, Gavel, Activity, Phone, Send, LogIn, LayoutDashboard, Database, MapPin, MessageCircle, BedDouble, Star, ShieldCheck, Clock, Video, ThumbsUp, Award, Filter, Newspaper, TrendingUp, BadgeCheck, Flag, Share2, Eye, Heart, PenLine, Trash2, Plus, Reply, UserCheck } from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from "recharts";
import { api } from "./api";
import { emergency } from "./data";

function ChatWidget(){
  const [open,setOpen]=useState(false);
  const [step,setStep]=useState("pick");
  const [places,setPlaces]=useState([]);
  const [q,setQ]=useState("");
  const [picked,setPicked]=useState(null);
  const [thread,setThread]=useState(null);
  const [draft,setDraft]=useState("");
  const [busy,setBusy]=useState(false);
  const [err,setErr]=useState("");
  const boxRef=useRef(null);

  useEffect(()=>{if(open&&step==="pick"&&!places.length)api.upazilas().then(setPlaces).catch(()=>setErr("Could not load upazilas."))},[open,step,places.length]);
  useEffect(()=>{
    if(!open||step!=="chat"||!thread)return;
    const poll=()=>api.thread(thread.id).then(r=>setThread(r.thread)).catch(()=>{});
    const t=setInterval(poll,5000);
    return()=>clearInterval(t);
  },[open,step,thread&&thread.id]);
  useEffect(()=>{const el=boxRef.current;if(el)el.scrollTop=el.scrollHeight},[thread&&thread.messages.length]);

  const matches=useMemo(()=>{const s=q.trim().toLowerCase();const list=s?places.filter(p=>p.name.toLowerCase().includes(s)||p.district.toLowerCase().includes(s)):places;const by={};list.forEach(p=>{(by[p.district]=by[p.district]||[]).push(p)});return by},[places,q]);

  const start=()=>{if(!draft.trim()||!picked)return;setBusy(true);setErr("");api.startThread(picked.id,draft.trim()).then(r=>{setThread(r.thread);setDraft("");setStep("chat")}).catch(e=>setErr(e.message)).finally(()=>setBusy(false))};
  const send=()=>{if(!draft.trim())return;setBusy(true);setErr("");api.postMessage(thread.id,draft.trim()).then(r=>setThread(r.thread)).catch(e=>setErr(e.message)).finally(()=>setDraft(""))};

  if(!open)return <button className="chat-fab" onClick={()=>setOpen(true)} aria-label="Open help chat"><MessageCircle size={22}/><span>Help</span></button>;

  return <div className="chat-panel" role="dialog" aria-label="Upazila help chat">
    <div className="chat-head">
      <div><b>{step==="pick"?"Upazila help desk":"Your conversation"}</b><span>{step==="pick"?"Choose your upazila to start":(thread?thread.district+" · "+thread.upazila:"")}</span></div>
      <button onClick={()=>{setOpen(false)}} aria-label="Close chat"><X size={17}/></button>
    </div>

    {step==="pick"&&<div className="chat-body">
      <div className="searchbox chat-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search upazila or district"/></div>
      {picked&&<div className="chat-picked"><CheckCircle2 size={15}/><div><b>{picked.name}</b><span>{picked.district} District</span></div><button onClick={()=>setPicked(null)}>Change</button></div>}
      {!picked&&<div className="chat-list">{Object.keys(matches).length?Object.keys(matches).map(d=><div key={d}><h5>{d} District</h5>{matches[d].map(p=><button key={p.id} onClick={()=>setPicked(p)}>{p.name}</button>)}</div>):<p className="chat-empty">No upazila matched.</p>}</div>}
      {picked&&<div className="chat-compose"><textarea value={draft} onChange={e=>setDraft(e.target.value)} placeholder="Describe what you need help with..." maxLength={2000} rows={3}/><button className="btn btn-primary full" disabled={busy||!draft.trim()} onClick={start}>{busy?"Sending...":"Start conversation"}</button></div>}
      {err&&<p className="chat-err">{err}</p>}
    </div>}

    {step==="chat"&&<>
      <div className="chat-messages" ref={boxRef}>
        {(thread&&thread.messages||[]).map(m=><div key={m.id} className={"chat-bubble "+m.sender.toLowerCase()}>{m.body}<span>{m.sender==="STAFF"?"Support":"You"} · {new Date(m.created_at).toLocaleString()}</span></div>)}
        {thread&&thread.status==="CLOSED"&&<p className="chat-closed">This conversation is closed.</p>}
      </div>
      {thread&&thread.status!=="CLOSED"&&<div className="chat-compose"><textarea value={draft} onChange={e=>setDraft(e.target.value)} placeholder="Write a reply..." maxLength={2000} rows={2} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}}/><button className="btn btn-primary full" disabled={busy||!draft.trim()} onClick={send}>{busy?"Sending...":"Send"}</button></div>}
      {err&&<p className="chat-err">{err}</p>}
    </>}
  </div>;
}
function ApiStatus(){const [state,setState]=useState("checking");useEffect(()=>{let alive=true;const ping=()=>{api.health().then(()=>{if(alive)setState("online")}).catch(()=>{if(alive)setState("offline")})};ping();const timer=setInterval(ping,30000);return()=>{alive=false;clearInterval(timer)}},[]);const map={checking:["amber","Checking API…"],online:["green","API online"],offline:["red","API offline"]};const[color,label]=map[state];return <div><b>System status</b><p className="api-status"><i className={"dot "+color}/>{label}</p></div>}
function Layout({children}) { const [open,setOpen]=useState(false); const [user,setUser]=useState(null); const nav=[["/","Home",Shield],["/map","Safety Map",Map],["/statistics","Statistics",BarChart3],["/cities","Districts",Building2],["/cases","Cases",FileText],["/journal","Journal",Newspaper],["/hotels","Safe Hotels",BedDouble],["/report","Report",Send],["/emergency","Help",Siren]]; useEffect(()=>{api.me().then(x=>x.authenticated&&setUser(x.user)).catch(()=>{});},[]); return <div className="app-shell"><header className="topbar"><Link to="/" className="brand" onClick={()=>setOpen(false)}><span className="brand-mark"><Shield size={19}/></span><span>Social Safety <b>BD</b></span></Link><button className="mobile-menu" onClick={()=>setOpen(v=>!v)} aria-label="Menu">{open?<X/>:<Menu/>}</button><nav className={open?"nav open":"nav"}>{nav.map(([to,label,Icon])=><NavLink key={to} to={to} end={to==="/"} onClick={()=>setOpen(false)}><Icon size={15}/>{label}</NavLink>)}</nav><div className="top-actions">{user?<><Link className="btn btn-ghost small" to={user.is_staff?"/admin":"/report"}>{user.is_staff?"Admin":"My reports"}</Link><button className="btn btn-primary small" onClick={()=>api.logout().then(()=>location.href="/")}>Logout</button></>:<><Link className="btn btn-ghost small" to="/login"><LogIn size={15}/> Login</Link><Link className="btn btn-primary small" to="/register">Register</Link></>}</div></header><div className="demo-banner"><AlertTriangle size={14}/><span>Prototype build &mdash; every statistic here is <b>synthetic demo data</b>, not a real crime figure. Replace with authoritative sources before publishing.</span></div><main>{children}</main><footer className="footer"><div><span className="brand"><span className="brand-mark"><Shield size={17}/></span>Social Safety BD</span><p>Public safety awareness and verified statistics prototype.</p></div><div><b>Responsible data</b><p>Verified records only. No victim identities or unverified accusations.</p></div><div><b>Emergency</b><p>For immediate danger, contact local emergency services.</p></div><ApiStatus/></footer><ChatWidget/></div> }
function StatCard({icon:Icon,label,value}){return <div className="stat-card"><div className="stat-icon"><Icon size={19}/></div><div><span>{label}</span><strong>{value}</strong></div></div>}
function PageTitle({eyebrow,title,text}){return <div className="page-title"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>}
function Loading(){return <div className="panel loading">Loading live data…</div>}
function ErrorBox({message}){return <div className="notice"><AlertTriangle size={17}/><div><b>Unable to load live data</b><span>{message||"Check that the Django backend is running."}</span></div></div>}
function Home(){const [s,setS]=useState(null);useEffect(()=>{api.statistics().then(setS).catch(()=>{})},[]);return <Layout><div className="container"><section className="hero"><div className="hero-copy"><span className="eyebrow"><Shield size={14}/> SAFETY INTELLIGENCE PLATFORM</span><h1>Stay aware.<br/><span>Stay safer.</span></h1><p>Explore verified public safety statistics, case outcomes, local resources and emergency services across Bangladesh.</p><div className="hero-actions"><Link className="btn btn-primary" to="/map">Explore Safety Map <ArrowRight size={17}/></Link><Link className="btn btn-light" to="/statistics">View Statistics</Link></div><div className="hero-note"><CheckCircle2 size={15}/> Awareness platform — not a public accusation or doxxing service.</div></div><div className="hero-panel"><div className="mini-map"><div className="map-water"/><div className="bd-flag"><div className="bd-flag-wave"><svg viewBox="0 0 100 100" role="img" aria-label="Flag of Bangladesh"><rect width="100" height="100" fill="#006A4E"/><circle cx="45" cy="50" r="20" fill="#F42A41"/><g transform="translate(45,50) scale(0.4) translate(-47,-46.5)"><path fill="#fff" d="M3.1,2.7 L16.3,9.7 L38.8,11.3 L42.9,16.1 L51,24.2 L63.3,25.8 L67.3,29 L81.6,30.6 L87.8,33.9 L91.8,40.3 L87.8,46.8 L91.8,50 L87.8,62.9 L79.6,66.1 L73.5,71 L69.4,72.6 L63.3,69.4 L59.2,74.2 L55.1,80.6 L49,85.5 L44.9,87.1 L38.8,82.3 L32.7,80.6 L26.5,83.9 L20.4,82.3 L16.3,83.9 L12.2,87.1 L8.2,90.3 L4.1,85.5 L2,82.3 L6.1,74.2 L12.2,67.7 L16.3,58.1 L14.3,48.4 L8.2,38.7 L4.1,29 L6.1,21 L3.1,12.9 Z"/></g></svg><span className="bd-flag-sheen"/></div></div><div className="map-label"><MapPin size={14}/> Bangladesh</div></div></div></section>{s?<section className="stats-grid"><StatCard icon={Building2} label="Districts covered" value={s.cities}/><StatCard icon={FileText} label="Reported cases" value={s.reported.toLocaleString()}/><StatCard icon={Gavel} label="Convictions" value={s.convicted.toLocaleString()}/><StatCard icon={Activity} label="Data status" value="Verified API"/></section>:<Loading/>}<section className="section-grid"><div className="panel"><div className="panel-head"><div><span className="eyebrow">OVERVIEW</span><h2>Safety map</h2></div><Link to="/map" className="text-link">Open map <ArrowRight size={15}/></Link></div><div className="preview-map"><div className="map-shape"/><div className="legend"><span><i className="dot red"/>Higher reports</span><span><i className="dot amber"/>Moderate</span><span><i className="dot green"/>Lower</span></div></div></div><div className="panel emergency-panel"><div className="panel-head"><div><span className="eyebrow">QUICK ACCESS</span><h2>Emergency help</h2></div><Siren/></div>{emergency.map(e=><div className="emergency-row" key={e.number}><span className="emergency-icon"><Phone size={16}/></span><div><b>{e.title}</b><span>{e.detail}</span></div><strong>{e.number}</strong></div>)}<Link className="btn btn-dark full" to="/emergency">View support options</Link></div></section></div></Layout>}
function MapFocus({target}){const map=useMap();useEffect(()=>{if(target&&target.latitude!=null)map.flyTo([target.latitude,target.longitude],8,{duration:.7})},[target,map]);return null}
function SafetyMap(){const [cities,setCities]=useState([]);const [query,setQuery]=useState("");const [division,setDivision]=useState("");const [focus,setFocus]=useState(null);useEffect(()=>{api.cities().then(setCities).catch(()=>{})},[]);const divisions=useMemo(()=>[...new Set(cities.map(c=>c.division))].filter(Boolean).sort(),[cities]);const filtered=useMemo(()=>cities.filter(c=>(!query||c.name.toLowerCase().includes(query.toLowerCase())||(c.division||"").toLowerCase().includes(query.toLowerCase()))&&(!division||c.division===division)),[cities,query,division]);const top=useMemo(()=>[...filtered].sort((a,b)=>b.reported-a.reported).slice(0,10),[filtered]);const peak=useMemo(()=>Math.max(1,...cities.map(c=>c.reported)),[cities]);const tone=v=>v>=0.6?"#ef4444":v>=0.3?"#f59e0b":"#10a66a";return <Layout><div className="container page"><PageTitle eyebrow="LOCATION INTELLIGENCE" title="Safety Map" text="All 64 districts plotted with real coordinates. Counts are synthetic demo data and must be read with population and time context."/><div className="map-toolbar"><div className="searchbox"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search district or division"/></div><div className="filter-pills"><button className={division?"":"active"} onClick={()=>setDivision("")}>All divisions</button>{divisions.map(d=><button key={d} className={division===d?"active":""} onClick={()=>setDivision(division===d?"":d)}>{d}</button>)}</div></div><div className="map-layout"><div className="large-map"><MapContainer center={[23.685,90.3563]} zoom={6} scrollWheelZoom><MapFocus target={focus}/><TileLayer attribution='&copy; OpenStreetMap contributors' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{filtered.filter(c=>c.latitude!=null&&c.longitude!=null).map(c=>{const t=tone(c.reported/peak);return <CircleMarker key={c.slug} center={[c.latitude,c.longitude]} radius={Math.max(7,Math.min(20,c.reported/25))} pathOptions={{color:t,fillColor:t,fillOpacity:.55,weight:2}} eventHandlers={{click:()=>setFocus(c)}}><Popup><b>{c.name}</b><br/><span style={{color:"#687890"}}>{c.division} Division</span><br/>{c.reported.toLocaleString()} reported cases<br/>{c.convicted} convictions<br/><Link to={'/cities/'+c.slug}>View profile</Link></Popup></CircleMarker>})}</MapContainer><div className="map-legend"><b>Reported volume</b><span><i style={{background:"#ef4444"}}/>High</span><span><i style={{background:"#f59e0b"}}/>Moderate</span><span><i style={{background:"#10a66a"}}/>Lower</span><em>Colour and size are relative to the highest district (synthetic data)</em></div></div><div className="panel map-side"><div className="panel-head"><div><span className="eyebrow">DISTRICT RANKING</span><h2>Bangladesh</h2></div></div><p className="map-count">Showing {filtered.length} of {cities.length} districts &middot; click to zoom</p>{top.map(c=><button className={"side-stat"+(focus&&focus.slug===c.slug?" active":"")} key={c.slug} onClick={()=>setFocus(focus&&focus.slug===c.slug?null:c)}><span><i className="dot" style={{background:tone(c.reported/peak)}}/>{c.name}</span><b>{c.reported.toLocaleString()}</b></button>)}</div></div></div></Layout>}
function Statistics(){const [s,setS]=useState(null);useEffect(()=>{api.statistics().then(setS).catch(()=>{})},[]);if(!s)return <Layout><div className="container page"><PageTitle eyebrow="DATA EXPLORER" title="Statistics" text="Live statistics from the Django API."/><Loading/></div></Layout>;const status=s.case_status.map(x=>({name:x.status,value:x.count}));return <Layout><div className="container page"><PageTitle eyebrow="DATA EXPLORER" title="Statistics" text="Live statistics from verified case records and city aggregates."/><div className="stats-grid"><StatCard icon={FileText} label="Total reported" value={s.reported.toLocaleString()}/><StatCard icon={Gavel} label="Convicted" value={s.convicted.toLocaleString()}/><StatCard icon={Building2} label="Districts" value={s.cities}/><StatCard icon={Database} label="Source status" value="API"/></div><div className="chart-grid"><ChartPanel title="Reported vs convicted by district (top 12)"><ResponsiveContainer width="100%" height={320}><BarChart data={s.city_totals.slice(0,12)}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis/><Tooltip/><Bar dataKey="reported_cases" fill="#0f6fff"/><Bar dataKey="convicted" fill="#10a66a"/></BarChart></ResponsiveContainer></ChartPanel><ChartPanel title="Verified case status"><ResponsiveContainer width="100%" height={320}><PieChart><Pie data={status} dataKey="value" nameKey="name" innerRadius={70} outerRadius={105}>{status.map((x,i)=><Cell key={x.name} fill={["#0f6fff","#7c5cff","#f59e0b","#10a66a","#ef4444"][i%5]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer></ChartPanel></div></div></Layout>}
function ChartPanel({title,children}){return <div className="panel chart-panel"><div className="panel-head"><div><span className="eyebrow">ANALYTICS</span><h2>{title}</h2></div></div>{children}</div>}
function Cities(){const [cities,setCities]=useState([]);useEffect(()=>{api.cities().then(setCities).catch(()=>{})},[]);const max=useMemo(()=>Math.max(1,...cities.map(c=>c.reported)),[cities]);return <Layout><div className="container page"><PageTitle eyebrow="DISTRICT DIRECTORY" title="Districts" text={`All ${cities.length} districts of Bangladesh, with synthetic demo statistics.`}/><div className="city-grid wide">{cities.map(c=><Link className="city-card" key={c.slug} to={'/cities/'+c.slug}><div className="city-photo"><span>{c.name.slice(0,2).toUpperCase()}</span></div><div className="city-info"><h3>{c.name}</h3><p>{c.division} &middot; {c.reported.toLocaleString()} reported cases <ArrowRight size={14}/></p><div className="meter"><i style={{width:Math.round(c.reported/max*100)+"%"}}/></div></div></Link>)}</div></div></Layout>}
function CityPage(){const {slug}=useParams();const [city,setCity]=useState(null);useEffect(()=>{api.cities().then(cs=>setCity(cs.find(c=>c.slug===slug))).catch(()=>{})},[slug]);if(!city)return <Layout><div className="container page"><Loading/></div></Layout>;return <Layout><div className="container page"><div className="city-hero"><div><span className="eyebrow">CITY SAFETY PROFILE</span><h1>{city.name}</h1><p>{city.division} Division &middot; synthetic demo statistics from the backend. Values must be replaced with authoritative sources before publication.</p></div><Link className="btn btn-light" to="/map"><Map size={16}/> Open map</Link></div><div className="stats-grid"><StatCard icon={FileText} label="Reported" value={city.reported}/><StatCard icon={Activity} label="Investigation" value={city.investigation}/><StatCard icon={Gavel} label="Under trial" value={city.trial}/><StatCard icon={CheckCircle2} label="Convicted" value={city.convicted}/></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">AREA DATA</span><h2>{city.name} areas</h2></div></div><AreaList city={city.slug}/></div></div></Layout>}
function AreaList({city}){const [areas,setAreas]=useState([]);useEffect(()=>{api.areas(city).then(setAreas).catch(()=>{})},[city]);return <div className="table-wrap"><table><thead><tr><th>Area</th><th>Reported</th><th>Investigation</th><th>Trial</th><th>Convicted</th></tr></thead><tbody>{areas.map(a=><tr key={a.id}><td><b>{a.name}</b></td><td>{a.reported}</td><td>{a.investigation}</td><td>{a.trial}</td><td>{a.convicted}</td></tr>)}</tbody></table></div>}
function CasePage(){const {caseId}=useParams();const [data,setData]=useState(null);const [error,setError]=useState("");useEffect(()=>{api.caseDetail(decodeURIComponent(caseId)).then(setData).catch(e=>setError(e.message))},[caseId]);if(error)return <Layout><div className="container page"><PageTitle eyebrow="CASE RECORD" title="Case not available" text="This case could not be loaded."/><ErrorBox message={error}/><Link className="btn btn-light" to="/cases"><ArrowRight size={16}/> Back to all cases</Link></div></Layout>;if(!data)return <Layout><div className="container page"><Loading/></div></Layout>;const rows=[["Case ID",data.case_id],["Status",data.status],["Court status",data.court_status],["Incident date",data.incident_date||"—"],["District",data.city],["Area",data.area||"—"],["Offence section",data.offence_section||"General public safety record"],["Verification",data.verified?"Verified record":"Not verified"],["Source",data.source_name]];return <Layout><div className="container page"><div className="city-hero"><div><span className="eyebrow">CASE RECORD</span><h1>{data.case_id}</h1><p>{data.city}{data.area?` · ${data.area}`:""} &middot; {data.status.replace(/_/g," ")}</p></div><Link className="btn btn-light" to="/cases"><ArrowRight size={16}/> All cases</Link></div>{data.verified&&<div className="notice success-notice"><CheckCircle2 size={17}/><div><b>Verified public record</b><span>No personal identities, photographs or unproven accusations are published for this case.</span></div></div>}<div className="panel"><div className="panel-head"><div><span className="eyebrow">DETAILS</span><h2>Case information</h2></div></div><div className="table-wrap"><table><tbody>{rows.map(([k,v])=><tr key={k}><th style={{width:"220px",textAlign:"left"}}>{k}</th><td>{k==="Source"&&data.source_url?<a href={data.source_url} target="_blank" rel="noreferrer">{v}</a>:v}</td></tr>)}</tbody></table></div></div></div></Layout>}
function Cases(){const [data,setData]=useState([]),[search,setSearch]=useState(""),[status,setStatus]=useState(""),[category,setCategory]=useState("");const load=()=>api.cases({search,status,category}).then(setData).catch(()=>setData([]));useEffect(()=>{load()},[status,category]);return <Layout><div className="container page"><PageTitle eyebrow="VERIFIED RECORDS" title="Case Records" text="Classified by offence and cited to the governing statute. No personal identities, photographs or unproven accusations are published."/><div className="panel"><div className="table-tools"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&load()} placeholder="Search case ID, city or area"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option><option value="REPORTED">Reported</option><option value="INVESTIGATION">Investigation</option><option value="TRIAL">Under Trial</option><option value="CONVICTED">Convicted</option><option value="ACQUITTED">Acquitted</option></select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option><option value="SEXUAL_OFFENCE">Sexual offence</option><option value="VIOLENCE">Violence</option><option value="TRAFFICKING">Trafficking / exploitation</option><option value="CYBERCRIME">Cybercrime</option><option value="GENERAL">General</option></select><button className="btn btn-primary" onClick={load}>Search</button></div><div className="table-wrap"><table><thead><tr><th>Case ID</th><th>Location</th><th>Category</th><th>Offence section</th><th>Status</th><th>Court status</th><th>Date</th><th>Source</th></tr></thead><tbody>{data.map(c=><tr key={c.case_id}><td><Link to={'/cases/'+encodeURIComponent(c.case_id)}><b>{c.case_id}</b></Link></td><td>{c.city}{c.area?` · ${c.area}`:""}</td><td>{c.category_label}</td><td>{c.offence_section||"—"}</td><td>{c.status}</td><td>{c.court_status}</td><td>{c.incident_date||"—"}</td><td>{c.source_url?<a href={c.source_url} target="_blank" rel="noreferrer">{c.source_name}</a>:c.source_name}</td></tr>)}</tbody></table>{!data.length&&<div className="empty">No verified cases found.</div>}</div></div></div></Layout>}
function Report(){const [sent,setSent]=useState(false),[error,setError]=useState("");const submit=e=>{e.preventDefault();setError("");const f=new FormData(e.currentTarget);api.submitReport(f).then(()=>{setSent(true);e.currentTarget.reset()}).catch(x=>setError(x.message))};return <Layout><div className="container narrow page"><PageTitle eyebrow="COMMUNITY REPORTING" title="Report an Incident" text="Reports enter a review queue and are not automatically treated as verified facts."/><form className="panel form" onSubmit={submit}><label>Location<input name="location" required placeholder="Area or general location"/></label><label>Category<select name="category" required><option value="">Select category</option><option>Safety concern</option><option>Incident information</option><option>Public service issue</option></select></label><label>Description<textarea name="description" rows="6" required maxLength="5000" placeholder="Describe the information for reviewers…"/></label><label>Evidence (optional)<input name="evidence" type="file" accept="image/*,.pdf"/></label><button className="btn btn-primary full"><Send size={16}/> Submit for review</button>{sent&&<div className="success"><CheckCircle2 size={17}/> Report submitted successfully.</div>}{error&&<ErrorBox message={error}/>}</form></div></Layout>}
function Auth({register=false}){const nav=useNavigate();const [form,setForm]=useState({name:"",email:"",password:""}),[error,setError]=useState("");const submit=e=>{e.preventDefault();setError("");const action=register?api.register(form.name,form.email,form.password):api.login(form.email,form.password);action.then(()=>nav("/")).catch(x=>setError(x.message))};return <Layout><div className="auth-page"><div className="auth-card"><div className="brand centered"><span className="brand-mark"><Shield size={19}/></span>Social Safety BD</div><h1>{register?"Create account":"Welcome back"}</h1><p>{register?"Create a community account.":"Sign in to continue."}</p><form className="form" onSubmit={submit}>{register&&<label>Full name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required placeholder="Your name"/></label>}<label>Email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required placeholder="you@example.com"/></label><label>Password<input type="password" minLength="8" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} required placeholder="Minimum 8 characters"/></label><button className="btn btn-primary full">{register?"Create account":"Login"}</button>{error&&<ErrorBox message={error}/>}</form><p className="auth-switch">{register?"Already have an account?":"New here?"} <Link to={register?"/login":"/register"}>{register?"Login":"Register"}</Link></p></div></div></Layout>}
function Admin(){const [reports,setReports]=useState([]),[error,setError]=useState(""),[threads,setThreads]=useState([]),[active,setActive]=useState(null),[reply,setReply]=useState(""),[busy,setBusy]=useState(false),[hotelReviews,setHotelReviews]=useState([]),[journalFlags,setJournalFlags]=useState([]),[journalists,setJournalists]=useState([]);const load=()=>api.adminReports().then(setReports).catch(e=>setError(e.message));const loadThreads=()=>api.adminThreads().then(ts=>{setThreads(ts);setActive(cur=>cur?ts.find(t=>t.id===cur.id)||ts[0]||null:ts[0]||null)}).catch(()=>{});const loadHotelReviews=()=>api.adminHotelReviews().then(setHotelReviews).catch(()=>{});const loadJournalFlags=()=>api.adminJournalFlags().then(r=>setJournalFlags(r.results||[])).catch(()=>{});const loadJournalists=()=>api.adminJournalists().then(r=>setJournalists(r.results||[])).catch(()=>{});useEffect(()=>{load()},[]);useEffect(()=>{loadThreads()},[]);useEffect(()=>{loadHotelReviews()},[]);useEffect(()=>{loadJournalFlags()},[]);useEffect(()=>{loadJournalists()},[]);const setReviewStatus=(id,status)=>api.moderateHotelReview(id,status).then(loadHotelReviews).catch(e=>setError(e.message));const setJournalFlagStatus=(id,status)=>api.resolveJournalFlag(id,status).then(loadJournalFlags).catch(e=>setError(e.message));const setJournalistStatus=(id,status)=>api.reviewJournalist(id,status).then(loadJournalists).catch(e=>setError(e.message));const send=()=>{if(!reply.trim()||!active)return;setBusy(true);api.staffReply(active.id,reply.trim(),active.status).then(r=>{setActive(r.thread);setReply("");loadThreads()}).catch(e=>setError(e.message)).finally(()=>setBusy(false))};const openCount=threads.filter(t=>t.status==="OPEN").length;return <Layout><div className="container page"><PageTitle eyebrow="ADMINISTRATION" title="Moderation Dashboard" text="Staff-only review queue for community reports and upazila help conversations."/>{error?<ErrorBox message={error}/>:<><div className="stats-grid"><StatCard icon={FileText} label="Safety reports" value={reports.length}/><StatCard icon={MessageCircle} label="Chat threads" value={threads.length}/><StatCard icon={AlertTriangle} label="Awaiting reply" value={openCount}/><StatCard icon={CheckCircle2} label="Answered" value={threads.filter(t=>t.status==="ANSWERED").length}/><StatCard icon={Newspaper} label="Journal reports" value={journalFlags.length}/><StatCard icon={BadgeCheck} label="Journalist apps" value={journalists.filter(j=>j.status==="PENDING").length}/></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">MODERATION</span><h2>Report queue</h2></div><LayoutDashboard/></div><div className="table-wrap"><table><thead><tr><th>Location</th><th>Category</th><th>Description</th><th>Status</th><th>Action</th></tr></thead><tbody>{reports.map(r=><tr key={r.id}><td>{r.location}</td><td>{r.category}</td><td>{r.description}</td><td>{r.status}</td><td><select value={r.status} onChange={e=>api.updateReport(r.id,e.target.value).then(load)}><option>PENDING</option><option>VERIFIED</option><option>REJECTED</option></select></td></tr>)}</tbody></table>{!reports.length&&<div className="empty">No reports in the queue.</div>}</div></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">HELP DESK</span><h2>Upazila conversations</h2></div><MessageCircle/></div>{threads.length?<div className="admin-chat"><div className="thread-list">{threads.map(t=><button key={t.id} className={"thread-item"+(active&&active.id===t.id?" active":"")} onClick={()=>{setActive(t);setReply("")}}><b>{t.upazila}</b><span>{t.district} &middot; {t.messages.length} message(s)</span><i className={"tag "+t.status.toLowerCase()}>{t.status}</i></button>)}</div><div className="thread-view">{active&&<><div className="thread-head"><div><b>{active.upazila}</b><span>{active.district} District &middot; #{active.id}</span></div><select value={active.status} onChange={e=>api.staffReply(active.id,"",e.target.value).then(r=>{setActive(r.thread);loadThreads()})}><option>OPEN</option><option>ANSWERED</option><option>CLOSED</option></select></div><div className="thread-messages">{active.messages.map(m=><div key={m.id} className={"chat-bubble "+m.sender.toLowerCase()}>{m.body}<span>{m.sender==="STAFF"?"Support":"User"} &middot; {new Date(m.created_at).toLocaleString()}</span></div>)}</div><div className="chat-compose"><textarea value={reply} onChange={e=>setReply(e.target.value)} placeholder="Write an official reply..." maxLength={2000} rows={3}/><button className="btn btn-primary" disabled={busy||!reply.trim()} onClick={send}>{busy?"Sending...":"Send reply"}</button></div></>}</div></div>:<div className="empty">No help conversations yet.</div>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">HOTEL REVIEWS</span><h2>Safety review queue</h2></div>{hotelReviews.filter(r=>r.status==="PENDING").length>0&&<span className="tag amber">{hotelReviews.filter(r=>r.status==="PENDING").length} awaiting</span>}</div><p className="fine-print" style={{margin:"0 0 14px"}}>A review is invisible to the public until you mark it verified. Check the account is a genuine stay before approving.</p>{hotelReviews.length?<div className="table-wrap"><table><thead><tr><th>Hotel</th><th>Author</th><th>Ratings</th><th>Account</th><th>Status</th><th>Action</th></tr></thead><tbody>{hotelReviews.map(r=><tr key={r.id}><td><b>{r.hotel}</b><br/><span className="muted">{r.city}</span></td><td>{r.author}{r.solo_traveller&&<><br/><span className="tag">Solo</span></>}</td><td>{r.rating}/5<br/><span className="muted">safety {r.safety_rating}/5</span></td><td className="review-cell">{r.body}</td><td>{r.status}</td><td><select value={r.status} onChange={e=>setReviewStatus(r.id,e.target.value)}><option>PENDING</option><option>VERIFIED</option><option>REJECTED</option></select></td></tr>)}</tbody></table></div>:<div className="empty">No hotel reviews submitted yet.</div>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">CITIZEN JOURNAL</span><h2>Post report queue</h2></div>{journalFlags.filter(f=>f.status==="PENDING").length>0&&<span className="tag amber">{journalFlags.filter(f=>f.status==="PENDING").length} awaiting</span>}</div><p className="fine-print" style={{margin:"0 0 14px"}}>Readers can report a journal post or comment without an account. Action the content itself by rejecting the post on the <Link to="/journal">journal</Link>, then mark the report resolved here.</p>{journalFlags.length?<div className="table-wrap"><table><thead><tr><th>Reason</th><th>Target</th><th>Details</th><th>Reporter</th><th>Status</th><th>Action</th></tr></thead><tbody>{journalFlags.map(f=><tr key={f.id}><td><span className={"tag "+(f.status==="PENDING"?"amber":"")}>{pretty(f.reason)}</span></td><td>{f.post?<Link to={`/journal/${f.post}`}>Post #{f.post}</Link>:f.comment?`Comment #${f.comment}`:"—"}</td><td className="review-cell">{f.details||"—"}</td><td>{f.reporter||"—"}</td><td>{f.status}{f.resolution&&<><br/><span className="muted">{f.resolution}</span></>}</td><td>{f.status==="PENDING"?<select value="" onChange={e=>e.target.value&&setJournalFlagStatus(f.id,e.target.value)}><option value="">Choose…</option><option value="RESOLVED">Actioned</option><option value="DISMISSED">No action</option></select>:<span className="muted">Closed{f.handled_by?` by ${f.handled_by}`:""}</span>}</td></tr>)}</tbody></table></div>:<div className="empty">No journal reports filed.</div>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">TRUST &amp; SAFETY</span><h2>Journalist applications</h2></div><BadgeCheck/></div><p className="fine-print" style={{margin:"0 0 14px"}}>A badge marks a byline as reviewed by staff. It is not a licence to publish accusations, and it should be refused if the claim to cover cannot be checked.</p>{journalists.length?<div className="table-wrap"><table><thead><tr><th>Applicant</th><th>Outlet</th><th>Statement</th><th>Status</th><th>Action</th></tr></thead><tbody>{journalists.map(j=><tr key={j.id}><td><b>{j.name}</b><br/><span className="muted">{j.user}</span></td><td>{j.outlet||"—"}</td><td className="review-cell">{j.statement}</td><td>{j.status}{j.notes&&<><br/><span className="muted">{j.notes}</span></>}</td><td>{j.status==="PENDING"?<select value="" onChange={e=>e.target.value&&setJournalistStatus(j.id,e.target.value)}><option value="">Choose…</option><option value="APPROVED">Approve</option><option value="REJECTED">Reject</option></select>:<span className="muted">Decided{j.reviewed_by?` by ${j.reviewed_by}`:""}</span>}</td></tr>)}</tbody></table></div>:<div className="empty">No applications yet.</div>}</div></>}</div></Layout>}
function Emergency(){return <Layout><div className="container page"><PageTitle eyebrow="GET HELP" title="Emergency Help" text="If you are in immediate danger, contact emergency services. This website does not replace police, medical or legal assistance."/><div className="emergency-hero"><Phone size={30}/><div><span>EMERGENCY NUMBER</span><strong>999</strong><p>Immediate police, fire or ambulance assistance.</p></div><a className="btn btn-light" href="tel:999">Call 999</a></div><div className="emergency-grid">{emergency.slice(1).map(e=><div className="panel emergency-card" key={e.number}><span className="emergency-icon"><Phone size={18}/></span><h2>{e.title}</h2><strong>{e.number}</strong><p>{e.detail}</p></div>)}</div></div></Layout>}
function Stars({value,size=13}){const v=Number(value)||0;return <span className="stars" title={v?v+" out of 5":"Not yet rated"}>{[1,2,3,4,5].map(i=><Star key={i} size={size} className={i<=Math.round(v)?"star on":"star"}/>)}</span>}
function SafetyScore({value,reviews}){const v=Number(value)||0;const tone=v>=4?"good":v>=3?"mid":"low";return <div className={"safety-score "+tone}><ShieldCheck size={16}/><div><strong>{v?v.toFixed(1):"–"}</strong><span>Safety{reviews?` · ${reviews} review${reviews===1?"":"s"}`:" · no reviews yet"}</span></div></div>}

function HotelPhoto({hotel,className}){const [failed,setFailed]=useState(false);if(hotel.photo&&!failed)return <img className={className} src={hotel.photo} alt={`${hotel.name} — illustrative placeholder, not a real photograph`} loading="lazy" onError={()=>setFailed(true)}/>;return <div className={(className||"")+" photo-fallback"} aria-hidden="true"><span>{hotel.name.trim().charAt(0).toUpperCase()}</span></div>}

function HotelCard({hotel}){const a=hotel.amenities||{};return <Link to={"/hotels/"+hotel.id} className="hotel-card"><div className="hotel-media"><HotelPhoto hotel={hotel} className="hotel-img"/><div className="hotel-badges"><span className="tag price">{hotel.price_range==="PREMIUM"?"Premium":hotel.price_range==="MID"?"Mid-range":"Budget"}</span></div><span className={"hotel-score "+((hotel.safety_rating||0)>=4?"good":(hotel.safety_rating||0)>=3?"mid":"low")}><ShieldCheck size={13}/><b>{(hotel.safety_rating||0).toFixed(1)}</b><em>safety</em></span></div><div className="hotel-card-body"><div className="hotel-card-top"><div><h3>{hotel.name}</h3><p className="hotel-where"><MapPin size={13}/>{hotel.city}{hotel.area?` · ${hotel.area}`:""}</p></div></div><div className="hotel-ratings"><div className="overall"><span>Overall</span><div><Stars value={hotel.rating}/><b>{hotel.rating?Number(hotel.rating).toFixed(1):"–"}</b></div></div><span className="review-count">{hotel.review_count} review{hotel.review_count===1?"":"s"}</span></div><div className="hotel-amenities">{a.front_desk_24h&&<span title="24-hour front desk"><Clock size={13}/>24h desk</span>}{a.cctv&&<span title="CCTV"><Video size={13}/>CCTV</span>}{a.women_only_floor&&<span title="Women-only floor"><ShieldCheck size={13}/>Women-only floor</span>}{!a.front_desk_24h&&!a.cctv&&!a.women_only_floor&&<span className="muted">No safety amenities listed</span>}</div><span className="text-link">View reviews <ArrowRight size={14}/></span></div></Link>}

function Hotels(){const [data,setData]=useState([]),[all,setAll]=useState([]),[cities,setCities]=useState([]),[search,setSearch]=useState(""),[city,setCity]=useState(""),[price,setPrice]=useState(""),[floor,setFloor]=useState(""),[error,setError]=useState("");const load=()=>api.hotels({search,city,price,min_rating:floor}).then(r=>{setData(r);setError("")}).catch(e=>setError(e.message));useEffect(()=>{api.cities().then(setCities).catch(()=>{})},[]);useEffect(()=>{api.hotels().then(setAll).catch(()=>{})},[]);useEffect(()=>{load()},[city,price,floor]);const districts=cities.filter(c=>all.some(h=>h.city_slug===c.slug));return <Layout><div className="container page"><PageTitle eyebrow="TRAVEL SAFELY" title="Safe Hotels" text="Ratings come from other travellers, above all from people who stayed alone. Every review is read by a moderator before it appears, and a hotel is only listed once staff have verified it."/><div className="panel"><div className="table-tools"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&load()} placeholder="Search hotel, area or district"/></div><select value={city} onChange={e=>setCity(e.target.value)}><option value="">All districts</option>{districts.map(c=><option key={c.slug} value={c.slug}>{c.name}</option>)}</select><select value={price} onChange={e=>setPrice(e.target.value)}><option value="">Any price</option><option value="BUDGET">Budget</option><option value="MID">Mid-range</option><option value="PREMIUM">Premium</option></select><select value={floor} onChange={e=>setFloor(e.target.value)}><option value="">Any safety score</option><option value="4.5">Safety 4.5+</option><option value="4">Safety 4.0+</option><option value="3">Safety 3.0+</option></select><button className="btn btn-primary" onClick={load}>Search</button></div>{error&&<ErrorBox message={error}/>}<div className="hotel-grid">{data.map(h=><HotelCard key={h.id} hotel={h}/>)}</div>{!data.length&&!error&&<div className="empty">No verified hotels match those filters. A listing appears only after staff verification.</div>}</div><p className="fine-print"><AlertTriangle size={13}/>A safety rating is a traveller's account, not an inspection. Verified means a moderator read the review, not that the hotel was audited.</p></div></Layout>}

function ReviewForm({hotelId,onDone}){const [form,setForm]=useState({author_name:"",rating:5,safety_rating:5,solo_traveller:false,body:""}),[busy,setBusy]=useState(false),[error,setError]=useState(""),[done,setDone]=useState("");const set=(k,v)=>setForm(f=>({...f,[k]:v}));const submit=e=>{e.preventDefault();setBusy(true);setError("");api.submitHotelReview({...form,hotel:Number(hotelId),rating:Number(form.rating),safety_rating:Number(form.safety_rating)}).then(r=>{setDone(r.message);setForm({author_name:"",rating:5,safety_rating:5,solo_traveller:false,body:""});onDone&&onDone()}).catch(e=>setError(e.message)).finally(()=>setBusy(false))};if(done)return <div className="panel"><div className="success"><CheckCircle2 size={15}/>{done}</div><p className="fine-print">It will appear on this page once a moderator has read it.</p><button className="btn btn-ghost small" onClick={()=>setDone("")}>Write another review</button></div>;return <form className="panel form" onSubmit={submit}><div className="panel-head"><div><span className="eyebrow">SHARE YOUR STAY</span><h2>Rate this hotel</h2></div></div><label>Display name<input value={form.author_name} onChange={e=>set("author_name",e.target.value)} maxLength={80} placeholder="How your name appears"/></label><div className="rate-row"><div><span>Overall rating</span><div className="rate-pick">{[1,2,3,4,5].map(i=><button type="button" key={i} className={i<=form.rating?"star on":"star"} onClick={()=>set("rating",i)} aria-label={"Overall "+i}><Star size={19}/></button>)}</div></div><div><span>How safe did it feel?</span><div className="rate-pick">{[1,2,3,4,5].map(i=><button type="button" key={i} className={i<=form.safety_rating?"star on":"star"} onClick={()=>set("safety_rating",i)} aria-label={"Safety "+i}><ShieldCheck size={19}/></button>)}</div></div></div><label className="check-row"><input type="checkbox" checked={form.solo_traveller} onChange={e=>set("solo_traveller",e.target.checked)}/> I was travelling on my own</label><label>Your account<textarea value={form.body} onChange={e=>set("body",e.target.value)} rows={4} maxLength={2000} placeholder="What was the area like at night? Was anyone on the front desk? How did staff treat you?"/></label>{error&&<p className="form-err"><AlertTriangle size={14}/>{error}</p>}<button className="btn btn-primary" disabled={busy}>{busy?"Sending…":"Submit for review"}</button><p className="fine-print">Read by staff before publication. One review per account.</p></form>}

function HotelPage(){const {hotelId}=useParams();const [data,setData]=useState(null),[error,setError]=useState("");const load=()=>api.hotelDetail(hotelId).then(setData).catch(e=>setError(e.message));useEffect(()=>{setData(null);setError("");load()},[hotelId]);if(error)return <Layout><div className="container page"><PageTitle eyebrow="SAFE HOTELS" title="Not available" text="This listing cannot be shown."/><ErrorBox message={error}/><Link className="btn btn-ghost" to="/hotels">Back to all hotels</Link></div></Layout>;if(!data)return <Layout><div className="container page"><PageTitle eyebrow="SAFE HOTELS" title="Hotel" text="Loading verified reviews."/><Loading/></div></Layout>;const a=data.amenities||{},reviews=data.reviews||[],breakdown=data.safety_breakdown||[],total=breakdown.reduce((n,r)=>n+r.count,0);return <Layout><div className="container page"><Link className="back-link" to="/hotels">← All hotels</Link><div className="hotel-hero-media"><HotelPhoto hotel={data} className="hotel-hero-img"/><div className="hotel-hero-text"><span className="eyebrow">{data.city}{data.area?` · ${data.area}`:""}</span><h1>{data.name}</h1>{data.address&&<p className="hotel-addr"><MapPin size={14}/>{data.address}</p>}<div className="hotel-hero-badges"><span className="tag">{data.price_range==="PREMIUM"?"Premium":data.price_range==="MID"?"Mid-range":"Budget"}</span>{a.front_desk_24h&&<span className="tag good"><Clock size={13}/>24h front desk</span>}{a.cctv&&<span className="tag good"><Video size={13}/>CCTV</span>}{a.women_only_floor&&<span className="tag good"><ShieldCheck size={13}/>Women-only floor</span>}</div><p className="photo-note">Placeholder image, not a photograph of a real property.</p></div><div className="hotel-hero-score"><SafetyScore value={data.safety_rating} reviews={data.review_count}/><div className="hero-stars"><Stars value={data.rating} size={17}/><b>{data.rating?Number(data.rating).toFixed(1):"–"}</b><span>overall</span></div></div></div><div className="section-grid"><div><div className="panel"><div className="panel-head"><div><span className="eyebrow">VERIFIED REVIEWS</span><h2>{reviews.length?`${reviews.length} review${reviews.length===1?"":"s"}`:"No reviews yet"}</h2></div>{data.solo_reviews>0&&<span className="tag good"><Award size={13}/>{data.solo_reviews} solo traveller{data.solo_reviews===1?"":"s"}</span>}</div>{reviews.length?<div className="review-list">{reviews.map(r=><div className="review" key={r.id}><div className="review-head"><b>{r.author}</b><span>{new Date(r.created_at).toLocaleDateString()}</span>{r.solo_traveller&&<span className="tag">Solo</span>}</div><div className="review-stars"><span>Overall <Stars value={r.rating}/></span><span>Safety <Stars value={r.safety_rating}/></span></div><p>{r.body}</p></div>)}</div>:<div className="empty">No traveller has reviewed this hotel yet. Be the first.</div>}</div>{total>0&&<div className="panel"><div className="panel-head"><div><span className="eyebrow">BREAKDOWN</span><h2>How safety was rated</h2></div></div><div className="breakdown">{breakdown.map(row=><div className="break-row" key={row.stars}><span>{row.stars} <Star size={12} className="star on"/></span><div className="break-bar"><i style={{width:(row.count/total*100)+"%"}}/></div><b>{row.count}</b></div>)}</div></div>}</div><div><ReviewForm hotelId={data.id} onDone={load}/><div className="panel fine-panel"><p className="fine-print"><AlertTriangle size={13}/>Ratings appear only after a moderator approves them. A score is never assigned automatically.</p></div></div></div></div></Layout>}

const CATEGORIES=[["","All topics"],["GENERAL","General safety"],["VIOLENCE","Violence"],["SEXUAL_OFFENCE","Sexual offence"],["TRAFFICKING","Trafficking"],["CYBERCRIME","Cybercrime"]];
const FLAG_REASONS=[["MISINFORMATION","Misleading or unverified claim"],["PRIVACY","Reveals private information"],["ABUSE","Abuse or harassment"],["SPAM","Spam or advertising"],["OTHER","Something else"]];
const pretty=s=>String(s||"").replace(/_/g," ").toLowerCase().replace(/^./,c=>c.toUpperCase());
const ago=iso=>{const m=(Date.now()-new Date(iso).getTime())/60000;if(m<1)return "just now";if(m<60)return `${Math.round(m)} min ago`;if(m<1440)return `${Math.round(m/60)} h ago`;return `${Math.round(m/1440)} d ago`};

function CategoryTag({value}){return <span className={"tag "+(["CYBERCRIME","VIOLENCE","SEXUAL_OFFENCE","TRAFFICKING"].includes(value)?"warn":"")}>{pretty(value)}</span>}
function VerifiedBadge(){return <span className="tag good" title="Staff-verified journalist"><BadgeCheck size={13}/> Verified journalist</span>}

function PostCard({post,onLike,onShare}){return <article className="panel post-card">
  <div className="post-meta"><CategoryTag value={post.category}/><span className="muted"><MapPin size={12}/> {post.city}</span>{post.author_verified?<VerifiedBadge/>:<span className="muted">{post.author}</span>}<span className="muted">· {ago(post.created_at)}</span>{post.status!=="PUBLISHED"&&<span className="tag warn">{pretty(post.status)}</span>}</div>
  <h3 className="post-title">{post.title}</h3>
  <p className="post-body">{post.body}</p>
  <div className="post-actions">
    <button className={"act"+(post.liked?" on":"")} onClick={()=>onLike&&onLike(post)} aria-pressed={!!post.liked}><ThumbsUp size={15}/> {post.like_count}</button>
    <span className="act static"><MessageCircle size={15}/> {post.comment_count}</span>
    <span className="act static"><Share2 size={15}/> {post.share_count}</span>
    <span className="act static"><Eye size={15}/> {post.views}</span>
    <button className="act right" onClick={()=>onShare&&onShare(post)}><Share2 size={15}/> Share</button>
    <Link className="act right" to={`/journal/${post.id}`}>Open <ArrowRight size={14}/></Link>
  </div>
</article>}

function JournalFilters({cities,filter,setFilter,tab,setTab,onSearch,search,setSearch}){return <div className="panel journal-filters">
  <div className="chip-row">{[["feed","District feed"],["trending","Trending"],["all","All posts"]].map(([k,l])=><button key={k} className={"chip"+(tab===k?" on":"")} onClick={()=>setTab(k)}>{k==="trending"?<TrendingUp size={14}/>:null}{l}</button>)}</div>
  <div className="chip-row">
    <select value={filter.city} onChange={e=>setFilter({...filter,city:e.target.value})} aria-label="Filter by district"><option value="">All districts</option>{cities.map(c=><option key={c.id} value={c.slug}>{c.name}</option>)}</select>
    <select value={filter.category} onChange={e=>setFilter({...filter,category:e.target.value})} aria-label="Filter by topic">{CATEGORIES.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select>
    <div className="searchbox"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&onSearch()} placeholder="Search the journal"/></div>
    <button className="btn btn-ghost small" onClick={onSearch}><Filter size={14}/> Apply</button>
  </div>
</div>}


function JournalPage(){
  const [cities,setCities]=useState([]),[posts,setPosts]=useState([]),[stats,setStats]=useState(null),[tab,setTab]=useState("feed"),[error,setError]=useState(""),[busy,setBusy]=useState(false),[note,setNote]=useState("");
  const [filter,setFilter]=useState({city:"",category:""}),[search,setSearch]=useState("");
  const load=()=>{setBusy(true);setError("");const params={city:filter.city,category:filter.category,q:search};
    const call=tab==="trending"?api.trendingPosts({limit:20}):tab==="feed"?api.journalFeed({limit:20}):api.journalPosts({...params,limit:20});
    call.then(r=>setPosts(r.results||[])).catch(e=>setError(e.message)).finally(()=>setBusy(false))};
  useEffect(()=>{api.cities().then(setCities).catch(()=>{})},[]);
  useEffect(()=>{api.journalStats().then(setStats).catch(()=>{})},[]);
  useEffect(load,[tab,filter.city,filter.category]);
  const like=post=>api.toggleJournalLike(post.id,post.liked).then(load).catch(e=>setError(e.message));
  const share=post=>api.shareJournalPost(post.id,"LINK").then(()=>{setNote("Share recorded.");load()}).catch(e=>setError(e.message));
  return <Layout><div className="container page">
    <PageTitle eyebrow="CITIZEN JOURNAL" title="Community reports and local news" text="Posts filed by residents and verified journalists, grouped by district. Read, respond, and report anything that should not be here."/>
    <div className="journal-head-actions"><Link className="btn btn-primary" to="/journal/new"><Plus size={16}/> Write a post</Link><Link className="btn btn-ghost" to="/journal/mine"><LayoutDashboard size={15}/> My posts &amp; reach</Link></div>
    {stats&&<div className="stats-grid"><StatCard icon={Newspaper} label="Posts" value={stats.posts}/><StatCard icon={MessageCircle} label="Comments" value={stats.comments}/><StatCard icon={ThumbsUp} label="Likes" value={stats.likes}/><StatCard icon={Share2} label="Shares" value={stats.shares}/><StatCard icon={Flag} label="Awaiting review" value={stats.pending_flags}/></div>}
    <JournalFilters cities={cities} filter={filter} setFilter={setFilter} tab={tab} setTab={setTab} search={search} setSearch={setSearch} onSearch={load}/>
    {note&&<div className="success-notice"><CheckCircle2 size={16}/><span>{note}</span></div>}
    {error&&<ErrorBox message={error}/>}
    {busy&&!posts.length&&<Loading/>}
    {!busy&&!posts.length&&!error&&<div className="panel"><p className="muted">No posts match these filters yet. Try another district, or write the first one.</p></div>}
    <div className="journal-list">{posts.map(p=><PostCard key={p.id} post={p} onLike={like} onShare={share}/>)}</div>
  </div></Layout>}


function JournalPostPage(){
  const {postId}=useParams();
  const [post,setPost]=useState(null),[comments,setComments]=useState([]),[error,setError]=useState(""),[note,setNote]=useState(""),[draft,setDraft]=useState(""),[replyTo,setReplyTo]=useState(null),[reporting,setReporting]=useState(false),[user,setUser]=useState(null);
  const reload=()=>{api.journalPost(postId).then(setPost).catch(()=>{});api.postComments(postId).then(r=>setComments(r.results||[])).catch(()=>{})};
  useEffect(()=>{setPost(null);setError("");api.journalPost(postId).then(setPost).catch(e=>setError(e.message));api.postComments(postId).then(r=>setComments(r.results||[])).catch(()=>{});api.viewJournalPost(postId).catch(()=>{});api.me().then(x=>x.authenticated&&setUser(x.user)).catch(()=>{})},[postId]);
  const like=()=>api.toggleJournalLike(post.id,post.liked).then(reload).catch(e=>setError(e.message));
  const share=()=>api.shareJournalPost(post.id,"LINK").then(()=>{setNote("Share recorded.");reload()});
  const submit=e=>{e.preventDefault();if(!draft.trim())return;api.addComment(post.id,draft.trim(),replyTo&&replyTo.id).then(()=>{setDraft("");setReplyTo(null);reload()}).catch(e=>setError(e.message))};
  const flag=reason=>{setReporting(false);api.reportJournalPost(post.id,reason).then(()=>setNote("Thank you. Staff will review this.")).catch(e=>setError(e.message))};
  const remove=()=>{if(!confirm("Delete this post? This cannot be undone."))return;api.deleteJournalPost(post.id).then(()=>{location.href="/journal"})};
  const mine=!!(user&&post&&(user.is_staff||user.id===post.author_id));
  if(error&&!post)return <Layout><div className="container page"><PageTitle eyebrow="JOURNAL" title="Not available" text="This post cannot be shown."/><ErrorBox message={error}/><Link className="btn btn-ghost" to="/journal">← Back to the journal</Link></div></Layout>;
  if(!post)return <Layout><div className="container page"><Loading/></div></Layout>;
  return <Layout><div className="container page">
    <Link className="back-link" to="/journal">← All posts</Link>
    {note&&<div className="success-notice"><CheckCircle2 size={16}/><span>{note}</span></div>}
    {error&&<ErrorBox message={error}/>}
    <article className="panel post-detail">
      <div className="post-meta"><CategoryTag value={post.category}/><span className="muted"><MapPin size={12}/> {post.city}</span>{post.author_verified?<VerifiedBadge/>:<span className="muted">by {post.author}</span>}<span className="muted">· {ago(post.created_at)}</span>{post.status!=="PUBLISHED"&&<span className="tag warn">{pretty(post.status)}</span>}</div>
      <h1 className="post-detail-title">{post.title}</h1>
      <p className="post-detail-body">{post.body}</p>
      <div className="post-actions">
        <button className={"act"+(post.liked?" on":"")} onClick={like}><ThumbsUp size={15}/> {post.like_count}</button>
        <span className="act static"><MessageCircle size={15}/> {post.comment_count}</span>
        <span className="act static"><Share2 size={15}/> {post.share_count}</span>
        <span className="act static"><Eye size={15}/> {post.views}</span>
        <button className="act right" onClick={share}><Share2 size={15}/> Share</button>
        <div className="flag-wrap">
          <button className="act" onClick={()=>setReporting(v=>!v)}><Flag size={15}/> Report</button>
          {reporting&&<div className="panel flag-menu">{FLAG_REASONS.map(([v,l])=><button key={v} onClick={()=>flag(v)}>{l}</button>)}</div>}
        </div>
        {mine&&<button className="act right danger" onClick={remove}><Trash2 size={15}/> Delete</button>}
      </div>
    </article>
    <div className="panel"><div className="panel-head"><div><span className="eyebrow">DISCUSSION</span><h2>{comments.length} comment{comments.length===1?"":"s"}</h2></div><MessageCircle/></div>
      {user?<form className="comment-form" onSubmit={submit}>
        {replyTo&&<div className="replying-to">Replying to {replyTo.author}<button type="button" onClick={()=>setReplyTo(null)}>Cancel</button></div>}
        <textarea value={draft} onChange={e=>setDraft(e.target.value)} maxLength={2000} placeholder={replyTo?"Write a reply…":"Add a comment. Keep it factual and respectful."}/>
        <button className="btn btn-primary small" type="submit"><Send size={14}/> Post comment</button>
      </form>:<p className="muted"><Link to="/login">Sign in</Link> to join the discussion.</p>}
      <div className="comment-list">{comments.map(c=><div key={c.id} className="comment">
        <div className="comment-head"><b>{c.author}</b>{c.parent&&<span className="muted">· reply</span>}<span className="muted">· {ago(c.created_at)}</span></div>
        <p className="comment-body">{c.body}</p>
        <div className="post-actions">
          {user&&<button className={"act"+(c.liked?" on":"")} onClick={()=>api.toggleCommentLike(c.id,c.liked).then(reload)}><Heart size={14}/> {c.like_count}</button>}
          {user&&<button className="act" onClick={()=>setReplyTo(c)}><Reply size={14}/> Reply</button>}
        </div>
      </div>)}</div>
      {!comments.length&&<p className="muted">No comments yet.</p>}
    </div>
  </div></Layout>}


function JournalNew(){
  const [cities,setCities]=useState([]),[form,setForm]=useState({title:"",body:"",city:"",category:"GENERAL",author_name:""}),[error,setError]=useState(""),[busy,setBusy]=useState(false);
  useEffect(()=>{api.cities().then(setCities).catch(()=>{})},[]);
  const set=(k,v)=>setForm(f=>({...f,[k]:v}));
  const submit=e=>{e.preventDefault();setBusy(true);setError("");api.createJournalPost(form).then(r=>{location.href=`/journal/${r.post.id}`}).catch(e=>setError(e.message)).finally(()=>setBusy(false))};
  return <Layout><div className="container page">
    <Link className="back-link" to="/journal">← All posts</Link>
    <PageTitle eyebrow="WRITE" title="Post a community report" text="Describe what you saw or verified. Do not name victims or publish private details — reports that expose someone are removed."/>
    <form className="panel form" onSubmit={submit}>
      <label>Headline<input value={form.title} onChange={e=>set("title",e.target.value)} maxLength={200} required placeholder="Short, factual summary"/></label>
      <label>District<select value={form.city} onChange={e=>set("city",e.target.value)} required><option value="">Choose a district</option>{cities.map(c=><option key={c.id} value={c.slug}>{c.name}</option>)}</select></label>
      <label>Topic<select value={form.category} onChange={e=>set("category",e.target.value)}>{CATEGORIES.filter(([v])=>v).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>
      <label>Display name <span className="muted">(optional — blank uses your account name)</span><input value={form.author_name} onChange={e=>set("author_name",e.target.value)} maxLength={120} placeholder="How you want to be credited"/></label>
      <label>Details<textarea value={form.body} onChange={e=>set("body",e.target.value)} maxLength={5000} required rows={7} placeholder="What happened, where, and when. How did you verify it?"/></label>
      {error&&<p className="form-err">{error}</p>}
      <button className="btn btn-primary" type="submit" disabled={busy}>{busy?"Publishing…":<><Send size={15}/> Publish post</>}</button>
    </form>
  </div></Layout>}


function JournalMine(){
  const [posts,setPosts]=useState([]),[stats,setStats]=useState(null),[error,setError]=useState(""),[auth,setAuth]=useState(false),[note,setNote]=useState(""),[form,setForm]=useState({outlet:"",statement:""}),[busy,setBusy]=useState(false);
  const load=()=>{api.myJournalPosts().then(r=>setPosts(r.results||[])).catch(e=>setError(e.message));api.myJournalAnalytics().then(setStats).catch(()=>{})};
  useEffect(()=>{api.me().then(x=>setAuth(!!x.authenticated)).catch(()=>{})},[]);
  useEffect(()=>{if(auth)load()},[auth]);
  const apply=e=>{e.preventDefault();setBusy(true);api.applyJournalist(form).then(()=>{setNote("Application received. Staff will review it.");setForm({outlet:"",statement:""})}).catch(e=>setError(e.message)).finally(()=>setBusy(false))};
  const remove=id=>{if(!confirm("Delete this post?"))return;api.deleteJournalPost(id).then(load)};
  return <Layout><div className="container page">
    <PageTitle eyebrow="MY JOURNAL" title="Your posts and reach" text="Everything you have published, including anything a moderator has rejected, plus a view of how far it travelled."/>
    {error&&<ErrorBox message={error}/>}
    {note&&<div className="success-notice"><CheckCircle2 size={16}/><span>{note}</span></div>}
    {!auth&&<p className="muted"><Link to="/login">Sign in</Link> to see your posts and apply for the journalist badge.</p>}
    {auth&&stats&&<div className="stats-grid">
      <StatCard icon={Newspaper} label="Posts" value={stats.posts}/><StatCard icon={CheckCircle2} label="Published" value={stats.published}/><StatCard icon={Eye} label="Views" value={stats.views}/><StatCard icon={ThumbsUp} label="Likes" value={stats.likes_received}/><StatCard icon={Share2} label="Shares" value={stats.shares_received}/><StatCard icon={MessageCircle} label="Comments" value={stats.comments_received}/>
    </div>}
    {auth&&stats&&<div className={"panel journal-badge"+(stats.journalist_badge?" good":"")}><BadgeCheck size={20}/><div><b>{stats.journalist_badge?"You carry the verified journalist badge":"Not yet verified"}</b><span>{stats.journalist_badge?"Staff have reviewed your credentials.":`${stats.flags_against_my_posts} report(s) filed against your posts.`}</span></div></div>}
    {auth&&<div className="panel"><div className="panel-head"><div><span className="eyebrow">PUBLISHED</span><h2>Your posts</h2></div><Newspaper/></div>
      {!posts.length&&<p className="muted">You have not posted yet. <Link to="/journal/new">Write your first post.</Link></p>}
      <div className="comment-list">{posts.map(p=><div key={p.id} className="comment"><div className="comment-head"><b>{p.title}</b><span className="muted">· {p.city}</span>{p.status!=="PUBLISHED"&&<span className="tag warn">{pretty(p.status)}</span>}</div><div className="post-actions"><span className="act static"><Eye size={14}/> {p.views}</span><span className="act static"><ThumbsUp size={14}/> {p.like_count}</span><span className="act static"><MessageCircle size={14}/> {p.comment_count}</span><Link className="act right" to={`/journal/${p.id}`}>Open</Link><button className="act right danger" onClick={()=>remove(p.id)}><Trash2 size={14}/> Delete</button></div></div>)}</div>
    </div>}
    {auth&&stats&&!stats.journalist_badge&&<form className="panel form" onSubmit={apply}>
      <div className="panel-head"><div><span className="eyebrow">JOURNALIST BADGE</span><h2>Apply for verification</h2></div><UserCheck/></div>
      <p className="muted">Staff check every application. A badge tells readers your byline has been reviewed — it is not a licence to publish accusations.</p>
      <label>Outlet or publication<input value={form.outlet} onChange={e=>setForm({...form,outlet:e.target.value})} maxLength={160} placeholder="Optional"/></label>
      <label>Tell us about your work<textarea value={form.statement} onChange={e=>setForm({...form,statement:e.target.value})} maxLength={2000} required rows={4} placeholder="Where you report, what you cover, links to past work."/></label>
      {error&&<p className="form-err">{error}</p>}
      <button className="btn btn-primary" type="submit" disabled={busy}><BadgeCheck size={15}/> Submit application</button>
    </form>}
  </div></Layout>}


function App(){return <Routes><Route path="/" element={<Home/>}/><Route path="/map" element={<SafetyMap/>}/><Route path="/statistics" element={<Statistics/>}/><Route path="/cities" element={<Cities/>}/><Route path="/cities/:slug" element={<CityPage/>}/><Route path="/cases" element={<Cases/>}/><Route path="/cases/:caseId" element={<CasePage/>}/><Route path="/journal" element={<JournalPage/>}/><Route path="/journal/new" element={<JournalNew/>}/><Route path="/journal/mine" element={<JournalMine/>}/><Route path="/journal/:postId" element={<JournalPostPage/>}/><Route path="/hotels" element={<Hotels/>}/><Route path="/hotels/:hotelId" element={<HotelPage/>}/><Route path="/report" element={<Report/>}/><Route path="/emergency" element={<Emergency/>}/><Route path="/login" element={<Auth/>}/><Route path="/register" element={<Auth register/>}/><Route path="/admin" element={<Admin/>}/></Routes>}
export default App;
